import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { DollarSign, ShoppingCart, TrendingUp, Award } from 'lucide-react';
import { fmt, getCurrentYM } from '../utils/format';
import { useSheets } from '../hooks/useSheets';
import { buildCostMap, calcShoplineTotals, calcMomoTotals, calcShopeeTotals, calcErpTotals, calcOrdersTotals } from '../utils/salesCalc';

const PLATFORM_COLORS = {
  shopline_raw: '#00c8ff', momo_raw: '#ff4488',
  shopee_raw: '#ffcc00', erp_raw: '#00e87a', orders: '#b44fff',
};

const CustomTooltip = ({ active, payload }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background:'rgba(15,20,40,0.95)', border:'1px solid rgba(0,245,255,0.3)', borderRadius:6, padding:'8px 14px', boxShadow:'0 0 16px rgba(0,245,255,0.15)' }}>
      <div style={{ fontWeight:600, color:'rgba(200,200,255,0.9)', marginBottom:4, fontSize:14 }}>{payload[0].payload.name}</div>
      <div style={{ color:'#00f5ff', fontFamily:'monospace', fontWeight:700, fontSize:14 }}>{fmt.currency(payload[0].value)}</div>
    </div>
  );
};

export default function Dashboard({ setPage, uploadStatus }) {
  const { year, month } = getCurrentYM();
  const { readAllSales, readProducts } = useSheets();
  const [data, setData] = useState({ revenue:0, cost:0, gross:0, net:0, grossRate:0, netRate:0, byPlatform:[], uploadsThisMonth:0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([readAllSales(), readProducts()]).then(([{ shopline, momo, shopee, erp, orders }, products]) => {
      // 依產品代號建立成本對照表，用來算真實的銷貨成本（不是用寫死的 0）
      const costMap = buildCostMap(products);

      // 計算各平台收入與成本（欄位對照 utils/salesCalc.js，跟 excelParser.js 實際寫入的欄位順序一致）
      const shopline_ = calcShoplineTotals(shopline, costMap);
      const momo_     = calcMomoTotals(momo, costMap);
      const shopee_   = calcShopeeTotals(shopee, costMap);
      const erp_      = calcErpTotals(erp, costMap);
      const orders_   = calcOrdersTotals(orders, costMap);

      const totalRevenue = shopline_.revenue + momo_.revenue + shopee_.revenue + erp_.revenue + orders_.revenue;
      const totalCost    = shopline_.cost + momo_.cost + shopee_.cost + erp_.cost + orders_.cost;
      const gross         = totalRevenue - totalCost;

      const byPlatform = [
        { name:'經銷', value: erp_.revenue },
        { name:'momo', value: momo_.revenue },
        { name:'官網', value: shopline_.revenue },
        { name:'蝦皮', value: shopee_.revenue },
        { name:'手動開單', value: orders_.revenue },
      ].filter(p => p.value > 0).sort((a,b) => b.value - a.value);

      // 首頁摘要目前沒有納入廣告費/其他費用（那些在損益表頁面才有），
      // 所以這裡的「淨利」等於「毛利」，只代表扣掉商品成本後的數字，不是最終的公司淨利。
      setData({ revenue: totalRevenue, cost: totalCost, gross, net: gross, grossRate:0, netRate:0, byPlatform });
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []); // eslint-disable-line

  const status = uploadStatus || {};
  const doneCount = Object.values(status).filter(v => v.done).length;
  const totalStores = 6;

  const metrics = [
    { label:'本月銷售收入', value: data.revenue, change: null, cls:'cyan', Icon: DollarSign },
    { label:'銷貨成本合計', value: data.cost,    change: null, cls:'pink', Icon: ShoppingCart },
    { label:'毛利 ／ 毛利率', value: data.gross, sub: data.revenue > 0 ? `毛利率 ${fmt.pct(data.gross/data.revenue)}` : '–', cls:'green', Icon: TrendingUp },
    { label:'本月淨利',       value: data.net,   sub: data.revenue > 0 ? `淨利率 ${fmt.pct(data.net/data.revenue)}` : '–', cls:'yellow', Icon: Award },
  ];

  return (
    <div>
      {loading && <div style={{ textAlign:'center', padding:'40px', color:'var(--muted)', fontSize:14 }}>載入中…</div>}

      <div className="metrics-grid" style={{ display:'grid', gridTemplateColumns:'repeat(2,1fr)', gap:12, marginBottom:20 }}>
        {metrics.map(({ label, value, change, sub, cls, Icon }) => (
          <div key={label} className={`metric-card metric-card--${cls}`}>
            <div className="metric-header">
              <span className="metric-label">{label}</span>
              <Icon size={18} className="metric-icon"/>
            </div>
            <div className="metric-value">{fmt.currency(value)}</div>
            {sub && <div className="metric-change" style={{ color:'var(--cyan)', fontWeight:600 }}>{sub}</div>}
            {change !== null && (
              <div className={`metric-change ${change >= 0 ? 'positive' : 'negative'}`}>
                {change >= 0 ? '↗' : '↘'} {fmt.pct(Math.abs(change))} 較上月
              </div>
            )}
          </div>
        ))}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, marginBottom:20 }}>
        {/* 各平台銷售金額 */}
        <div className="card">
          <div className="card-title">各平台銷售金額 <span>{year}年{month}月</span></div>
          {data.byPlatform.length === 0
            ? <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)', fontSize:14 }}>◻ 尚無資料，請先上傳報表</div>
            : <ResponsiveContainer width="100%" height={180}>
                <BarChart data={data.byPlatform} layout="vertical" margin={{ left:4, right:16, top:4, bottom:4 }}>
                  <XAxis type="number" hide/>
                  <YAxis type="category" dataKey="name" width={44} tick={{ fontSize:13, fill:'rgba(200,200,255,0.85)', fontFamily:'monospace' }}/>
                  <Tooltip content={<CustomTooltip/>} cursor={{ fill:'rgba(0,245,255,0.06)' }}/>
                  <Bar dataKey="value" radius={[0,3,3,0]}>
                    {data.byPlatform.map(e => (
                      <Cell key={e.name} fill={
                        e.name==='經銷'?'#00e87a': e.name==='momo'?'#ff4488':
                        e.name==='官網'?'#00c8ff': e.name==='蝦皮'?'#ffcc00':'#b44fff'
                      }/>
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
          }
        </div>

        {/* 報表上傳狀態 */}
        <div className="card">
          <div className="card-title">
            本月報表上傳狀態
            <span style={{ color: doneCount === totalStores ? 'var(--green)' : 'var(--yellow)' }}>
              △ {doneCount}/{totalStores} 已上傳
            </span>
          </div>
          {['TOOLA_SHOPLINE','TOOLA_SHOPEE','MOMO','TAKUYA_SHOPEE','TAKUYA_SHOPLINE','ERP'].map(id => {
            const labels = { TOOLA_SHOPLINE:'TOOLA_SHOPLINE 報表', TOOLA_SHOPEE:'TOOLA_SHOPEE 報表', MOMO:'MOMO 報表', TAKUYA_SHOPEE:'TAKUYA_SHOPEE 報表', TAKUYA_SHOPLINE:'TAKUYA_SHOPLINE 報表', ERP:'ERP 報表' };
            const done = status[id]?.done;
            return (
              <div key={id} onClick={() => setPage('upload')}
                style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 0', borderBottom:'1px solid var(--border)', cursor:'pointer' }}>
                <div style={{ width:8, height:8, borderRadius:'50%', background: done ? 'var(--green)' : 'var(--muted)', boxShadow: done ? '0 0 6px var(--green)' : 'none', flexShrink:0 }}/>
                <div>
                  <div style={{ fontSize:14, fontWeight:600 }}>{labels[id]}</div>
                  <div style={{ fontSize:12, color: done ? 'var(--green)' : 'var(--yellow)' }}>
                    {done ? `✓ 已匯入` : '待上傳 － 點擊前往'}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 本月損益摘要 */}
      <div className="card">
        <div className="card-title">本月損益摘要</div>
        {[
          { label:'銷貨收入', value: data.revenue, color:'var(--cyan)',   pct: 1 },
          { label:'銷貨成本', value: data.cost,    color:'var(--pink)',   pct: data.revenue > 0 ? data.cost/data.revenue : 0 },
          { label:'毛利',     value: data.gross,   color:'var(--green)',  pct: data.revenue > 0 ? data.gross/data.revenue : 0 },
        ].map(({ label, value, color, pct }) => (
          <div key={label} style={{ marginBottom:12 }}>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:4 }}>
              <span style={{ fontSize:14, color:'var(--muted)' }}>{label}</span>
              <span style={{ fontSize:14, color, fontFamily:'var(--mono)', fontWeight:600 }}>{fmt.currency(value)}</span>
            </div>
            <div style={{ height:4, background:'var(--bg3)', borderRadius:2 }}>
              <div style={{ height:'100%', width:`${Math.min(100, pct*100)}%`, background:color, borderRadius:2, boxShadow:`0 0 6px ${color}60`, transition:'width .5s' }}/>
            </div>
          </div>
        ))}
        <div style={{ marginTop:16, padding:'12px 16px', background: data.net >= 0 ? 'rgba(0,255,159,0.08)' : 'rgba(255,0,110,0.08)', borderRadius:4, border:`1px solid ${data.net >= 0 ? 'rgba(0,255,159,0.3)' : 'rgba(255,0,110,0.3)'}`, display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div>
            <div style={{ fontSize:13, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', letterSpacing:1 }}>本月淨利</div>
            <div style={{ fontSize:12, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', opacity:0.7 }}>淨利率 {data.revenue > 0 ? fmt.pct(data.net/data.revenue) : '–'}</div>
          </div>
          <div style={{ fontSize:26, fontWeight:700, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', fontFamily:'var(--title)', textShadow: `0 0 16px ${data.net >= 0 ? 'var(--green)' : 'var(--pink)'}60` }}>
            {fmt.currency(data.net)}
          </div>
        </div>
      </div>
    </div>
  );
}
